#!/usr/bin/env python3
"""Carve Zed unsaved-buffer text (editors.contents) out of raw SQLite pages.

Goes deeper than `sqlite3 .recover`: walks every page in the main DB *and*
every historical page image in the WAL, parsing each as a b-tree leaf
regardless of whether it is still reachable from a table root.

Read-only. Never writes to the source files.

Usage:
    python3 carve.py OUTDIR FILE [FILE ...]

    python3 carve.py carved_out pristine/db.sqlite.orig pristine/db.sqlite-wal.orig
"""

import hashlib
import os
import struct
import sys

PAGE_HEADER_LEAF = 0x0D  # table b-tree leaf


def varint(buf, off):
    """Decode a SQLite varint. Returns (value, bytes_consumed)."""
    val = 0
    for i in range(9):
        if off + i >= len(buf):
            return None, 0
        byte = buf[off + i]
        if i == 8:
            return (val << 8) | byte, 9
        val = (val << 7) | (byte & 0x7F)
        if not byte & 0x80:
            return val, i + 1
    return None, 0


def serial_len(stype):
    if stype in (0, 8, 9, 12, 13):
        return 0
    if stype in (1, 2, 3, 4):
        return stype
    if stype == 5:
        return 6
    if stype in (6, 7):
        return 8
    if stype >= 12:
        return (stype - 12) // 2
    return 0


def decode_record(payload):
    """Decode a SQLite record into a list of Python values. Best effort."""
    hdr_size, n = varint(payload, 0)
    if hdr_size is None or hdr_size > len(payload) or hdr_size < 1:
        return None
    stypes, off = [], n
    while off < hdr_size:
        st, n2 = varint(payload, off)
        if st is None or n2 == 0:
            return None
        stypes.append(st)
        off += n2
    vals, off = [], hdr_size
    for st in stypes:
        ln = serial_len(st)
        if off + ln > len(payload):
            vals.append(None)
            off += ln
            continue
        raw = payload[off : off + ln]
        if st == 0:
            vals.append(None)
        elif 1 <= st <= 6:
            vals.append(int.from_bytes(raw, "big", signed=True))
        elif st == 7:
            vals.append(struct.unpack(">d", raw)[0] if ln == 8 else None)
        elif st == 8:
            vals.append(0)
        elif st == 9:
            vals.append(1)
        elif st >= 12 and st % 2 == 0:
            vals.append(raw)  # blob
        elif st >= 13:
            vals.append(raw.decode("utf-8", errors="replace"))
        else:
            vals.append(None)
        off += ln
    return vals


def follow_overflow(db, pagesize, first_page, need):
    """Walk an overflow page chain, collecting `need` more payload bytes."""
    out, page, seen = b"", first_page, set()
    while page and need > 0 and page not in seen:
        seen.add(page)
        start = (page - 1) * pagesize
        if start + pagesize > len(db):
            break
        chunk = db[start : start + pagesize]
        nxt = int.from_bytes(chunk[:4], "big")
        take = min(need, pagesize - 4)
        out += chunk[4 : 4 + take]
        need -= take
        page = nxt
    return out


def parse_leaf_page(page, pagesize, db_for_overflow=None):
    """Yield decoded records from a page interpreted as a table b-tree leaf."""
    if not page or page[0] != PAGE_HEADER_LEAF:
        return
    ncells = int.from_bytes(page[3:5], "big")
    if ncells == 0 or ncells > (pagesize // 6):
        return
    usable = pagesize
    maxlocal = usable - 35
    minlocal = ((usable - 12) * 32 // 255) - 23
    for i in range(ncells):
        po = 8 + i * 2
        if po + 2 > len(page):
            break
        cell_off = int.from_bytes(page[po : po + 2], "big")
        if cell_off <= 0 or cell_off >= len(page):
            continue
        psize, n1 = varint(page, cell_off)
        if psize is None or n1 == 0 or psize <= 0 or psize > 100_000_000:
            continue
        _rowid, n2 = varint(page, cell_off + n1)
        if n2 == 0:
            continue
        data_off = cell_off + n1 + n2
        if psize <= maxlocal:
            payload = page[data_off : data_off + psize]
        else:
            local = minlocal + ((psize - minlocal) % (usable - 4))
            if local > maxlocal:
                local = minlocal
            payload = page[data_off : data_off + local]
            ovf_at = data_off + local
            if db_for_overflow is not None and ovf_at + 4 <= len(page):
                ovf = int.from_bytes(page[ovf_at : ovf_at + 4], "big")
                if 0 < ovf:
                    payload += follow_overflow(
                        db_for_overflow, pagesize, ovf, psize - local
                    )
        rec = decode_record(payload)
        if rec:
            yield rec


def looks_like_editor_row(rec):
    """editors: item_id, workspace_id, path, 3 scroll cols, contents, language, mtime*2, buffer_path"""
    if not (10 <= len(rec) <= 11):
        return False
    if not isinstance(rec[0], int) or not isinstance(rec[1], int):
        return False
    contents = rec[6] if len(rec) > 6 else None
    return isinstance(contents, str) and len(contents.strip()) > 2


def iter_pages(path):
    """Yield (label, pagesize, page_bytes) for a DB file or a WAL file."""
    with open(path, "rb") as f:
        blob = f.read()
    if blob[:6] == b"SQLite":
        pagesize = int.from_bytes(blob[16:18], "big")
        if pagesize == 1:
            pagesize = 65536
        for i in range(len(blob) // pagesize):
            yield f"db:page{i+1}", pagesize, blob[i * pagesize : (i + 1) * pagesize], blob
    else:
        # WAL: 32-byte header, then frames of (24-byte header + page)
        magic = int.from_bytes(blob[0:4], "big")
        if magic not in (0x377F0682, 0x377F0683):
            print(f"  ! {path}: not a DB or WAL, skipping", file=sys.stderr)
            return
        pagesize = int.from_bytes(blob[8:12], "big")
        framesize = 24 + pagesize
        nframes = (len(blob) - 32) // framesize
        for i in range(nframes):
            off = 32 + i * framesize + 24
            yield f"wal:frame{i+1}", pagesize, blob[off : off + pagesize], None


def main():
    if len(sys.argv) < 3:
        print(__doc__)
        sys.exit(1)
    outdir, sources = sys.argv[1], sys.argv[2:]
    os.makedirs(outdir, exist_ok=True)

    seen, found, pages_scanned = {}, 0, 0
    for src in sources:
        print(f"[*] scanning {src}")
        for label, pagesize, page, dbblob in iter_pages(src):
            pages_scanned += 1
            try:
                for rec in parse_leaf_page(page, pagesize, dbblob):
                    if not looks_like_editor_row(rec):
                        continue
                    text = rec[6]
                    h = hashlib.md5(text.encode("utf-8", "replace")).hexdigest()
                    if h in seen:
                        continue
                    seen[h] = (rec[0], rec[1], label, len(text))
                    found += 1
                    name = f"ws{rec[1]}_item{rec[0]}_{h[:8]}.txt"
                    with open(os.path.join(outdir, name), "w", errors="replace") as fh:
                        fh.write(text)
            except Exception:
                continue  # a garbage page is expected and not interesting

    print(f"\n[*] {pages_scanned} pages scanned, {found} unique buffers -> {outdir}/")
    for h, (item, ws, label, ln) in sorted(seen.items(), key=lambda x: -x[1][3]):
        print(f"    ws{ws:<6} item{item:<16} {ln:>9}b  {label}")


if __name__ == "__main__":
    main()

